 string keyHost="";endpoint.TextChanged+=(sender,args)=>{Uri address;if(Uri.TryCreate(endpoint.Text,UriKind.Absolute,out address)){if(keyHost!=""&&!string.Equals(keyHost,address.Host,StringComparison.OrdinalIgnoreCase))key.Clear();keyHost=address.Host;}};Action update=()=>{int i=provider.SelectedIndex;endpoint.IsEnabled=model.IsEnabled=key.IsEnabled=i!=3;endpoint.IsReadOnly=model.IsReadOnly=false;if(i==0){endpoint.Text=prefs.ContainsKey("endpoint")?prefs["endpoint"]:"";model.Text=prefs.ContainsKey("model")?prefs["model"]:"";note.Text="优先使用你自己的服务商。地址、模型和 Key 均可自由配置，填写兼容 Chat Completions 的完整接口地址。服务商如何计费，以其规则为准。";}if(i==1){endpoint.Text="https://openrouter.ai/api/v1/chat/completions";model.Text="openrouter/free";note.Text="已预填免费路由，留空 Key 可用内置公共额度，建议配置自己的 API。免费服务有速率和额度限制；若手动换成其他模型或接口，费用按新服务的规则计算。程序不会自动切换付费模型。";}if(i==2){endpoint.Text="http://127.0.0.1:11434/v1/chat/completions";model.Text="";note.Text="填写本机已安装模型的完整 ID。地址、模型与可选 Key 都可编辑。默认 Ollama 不需要 Key；本机调用不会把应用列表发送到云端。";}if(i==3){endpoint.Text=model.Text="";note.Text="本地规则不联网，不需要 Key，也没有 API 费用。它是规则分析，不是大模型；可直接使用，但仍需人工复核依赖。";}};provider.SelectionChanged+=(s,e)=>update();update();
