 }
 Dictionary<string,string> ReadAiPreferences(){try{string file=Data+"/ai-settings.json";if(File.Exists(file))return new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(File.ReadAllText(file))??new Dictionary<string,string>();}catch{}return new Dictionary<string,string>();}
 void ValidateAiAddress(string url){Uri uri;if(!Uri.TryCreate(url,UriKind.Absolute,out uri)||!(uri.Scheme=="https"||(uri.Scheme=="http"&&uri.IsLoopback)))throw new Exception("远程接口需使用 HTTPS；本地接口可使用 localhost / 127.0.0.1 的 HTTP。");}

 void LocalRuleAnalysis(){foreach(var p in packages)p.Pick=false;UseOriginalRules();Report("本地四类用途规则已更新（不是 AI）；未自动勾选或卸载应用。");}
 class AiClient:WebClient{protected override WebRequest GetWebRequest(Uri address){var r=base.GetWebRequest(address);r.Timeout=120000;var http=r as HttpWebRequest;if(http!=null){http.AllowAutoRedirect=false;if(address.IsLoopback)http.Proxy=null;http.ReadWriteTimeout=120000;}return r;}}
}


